1	'use strict';
2	
3	/**
4	 * Rock Skipping relay server.
5	 *
6	 * Routes messages between one Unity host (the PC driving the TV) and up to
7	 * MAX_PLAYERS_PER_ROOM phone controllers, keyed by a short room code.
8	 *
9	 * Routing is deliberately generic: the relay knows nothing about AIM, THROW or
10	 * SPECTATE. Anything a player sends goes to the host; anything the host sends
11	 * goes to every player, or to one player if it carries `targetPlayerId`. New
12	 * message types can be added to the game without touching this file.
13	 */
14	
15	const { WebSocketServer, WebSocket } = require('ws');
16	const qrcode = require('qrcode-generator');
17	const crypto = require('crypto');
18	const http = require('http');
19	const fs = require('fs');
20	const nodePath = require('path');
21	
22	const PORT = Number(process.env.PORT) || 3000;
23	const MAX_PLAYERS_PER_ROOM = 8;
24	const MAX_MESSAGE_BYTES = 4096;
25	const HEARTBEAT_MS = 30_000;
26	const ROOM_IDLE_TIMEOUT_MS = 4 * 60 * 60 * 1000; // 4 hours
27	const ROOM_SWEEP_MS = 5 * 60 * 1000;
28	const RATE_WINDOW_MS = 1000;
29	// AIM streams at the sensor rate (60Hz) while a player is gripping, so the ceiling
30	// has to sit well clear of that. At exactly 60 the limiter starts discarding aim
31	// frames the moment a throw or a heartbeat shares the same second — silently, since
32	// a flooding client deliberately gets no feedback — and the arc stutters for reasons
33	// that look nothing like rate limiting from the game side.
34	const RATE_MAX_MESSAGES = 180;
35	
36	// No I and no O — these are read aloud off a TV and typed on a phone.
37	const CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
38	const CODE_LENGTH = 4;
39	const MAX_PLAYER_ID_LENGTH = 16;
40	
41	// A join URL is well under this. The endpoint is reachable through the public
42	// tunnel, so it takes a bound rather than trusting the caller.
43	const MAX_QR_DATA_LENGTH = 512;
44	
45	/** @type {Map<string, {code: string, host: WebSocket, players: Map<string, WebSocket>, lastActivity: number}>} */
46	const rooms = new Map();
47	
48	// ---------------------------------------------------------------------------
49	// helpers
50	// ---------------------------------------------------------------------------
51	
52	function generateRoomCode() {
53	  // 24^4 = 331,776 combinations, so collisions are rare; retry a bounded number
54	  // of times rather than looping forever if the space somehow fills up.
55	  for (let attempt = 0; attempt < 100; attempt++) {
56	    let code = '';
57	    for (let i = 0; i < CODE_LENGTH; i++) {
58	      code += CODE_ALPHABET[crypto.randomInt(CODE_ALPHABET.length)];
59	    }
60	    if (!rooms.has(code)) return code;
61	  }
62	  return null;
63	}
64	
65	function send(ws, payload) {
66	  if (ws && ws.readyState === WebSocket.OPEN) {
67	    ws.send(JSON.stringify(payload));
68	  }
69	}
70	
71	function sendError(ws, code, message) {
72	  send(ws, { type: 'ERROR', code, message });
73	}
74	
75	function log(...args) {
76	  console.log(new Date().toISOString(), ...args);
77	}
78	
79	function sanitizePlayerId(raw) {
80	  if (typeof raw !== 'string') return null;
81	  const trimmed = raw.trim().toUpperCase().slice(0, MAX_PLAYER_ID_LENGTH);
82	  return trimmed.length > 0 ? trimmed : null;
83	}
84	
85	function normalizeRoomCode(raw) {
86	  if (typeof raw !== 'string') return null;
87	  const trimmed = raw.trim().toUpperCase();
88	  return trimmed.length === CODE_LENGTH ? trimmed : null;
89	}
90	
91	/** Rolling-window rate limit. Returns true if the message should be dropped. */
92	function isRateLimited(meta) {
93	  const now = Date.now();
94	  if (now - meta.rateWindowStart >= RATE_WINDOW_MS) {
95	    meta.rateWindowStart = now;
96	    meta.rateCount = 0;
97	  }
98	  meta.rateCount++;
99	  return meta.rateCount > RATE_MAX_MESSAGES;
100	}
101	
102	function closeRoom(room, reason) {
103	  for (const [, playerWs] of room.players) {
104	    send(playerWs, { type: 'ROOM_CLOSED', reason });
105	    if (playerWs.meta) playerWs.meta.roomCode = null;
106	    playerWs.close(1000, reason);
107	  }
108	  room.players.clear();
109	  rooms.delete(room.code);
110	  log(`room ${room.code} closed (${reason})`);
111	}
112	
113	// ---------------------------------------------------------------------------
114	// message handlers
115	// ---------------------------------------------------------------------------
116	
117	function handleCreateRoom(ws) {
118	  if (ws.meta.role) {
119	    sendError(ws, 'ALREADY_REGISTERED', 'This connection already has a role.');
120	    return;
121	  }
122	
123	  const code = generateRoomCode();
124	  if (!code) {
125	    sendError(ws, 'NO_CODES_AVAILABLE', 'Could not allocate a room code.');
126	    return;
127	  }
128	
129	  const room = { code, host: ws, players: new Map(), lastActivity: Date.now() };
130	  rooms.set(code, room);
131	
132	  ws.meta.role = 'host';
133	  ws.meta.roomCode = code;
134	
135	  send(ws, { type: 'ROOM_CREATED', roomCode: code });
136	  log(`room ${code} created`);
137	}
138	
139	function handleJoinRoom(ws, data) {
140	  if (ws.meta.role === 'host') {
141	    sendError(ws, 'HOST_CANNOT_JOIN', 'A host connection cannot join as a player.');
142	    return;
143	  }
144	
145	  const code = normalizeRoomCode(data.roomCode);
146	  if (!code) {
147	    sendError(ws, 'BAD_ROOM_CODE', 'Room codes are 4 letters.');
148	    return;
149	  }
150	
151	  const playerId = sanitizePlayerId(data.playerId);
152	  if (!playerId) {
153	    sendError(ws, 'BAD_PLAYER_ID', 'Please enter a name.');
154	    return;
155	  }
156	
157	  const room = rooms.get(code);
158	  // The original prototype stayed silent here, so the phone optimistically
159	  // showed the game screen for a room that never existed. Always answer.
160	  if (!room) {
161	    sendError(ws, 'ROOM_NOT_FOUND', `No game found with code ${code}.`);
162	    return;
163	  }
164	
165	  const existing = room.players.get(playerId);
166	  const isReconnect = Boolean(existing);
167	
168	  if (!isReconnect && room.players.size >= MAX_PLAYERS_PER_ROOM) {
169	    sendError(ws, 'ROOM_FULL', `This game is full (${MAX_PLAYERS_PER_ROOM} players).`);
170	    return;
171	  }
172	
173	  // Reconnect: a phone that slept or dropped Wi-Fi reclaims its slot by name.
174	  if (isReconnect && existing !== ws) {
175	    if (existing.meta) existing.meta.roomCode = null;
176	    existing.close(1000, 'Replaced by a new connection');
177	  }
178	
179	  room.players.set(playerId, ws);
180	  room.lastActivity = Date.now();
181	
182	  ws.meta.role = 'player';
183	  ws.meta.roomCode = code;
184	  ws.meta.playerId = playerId;
185	
186	  send(ws, { type: 'JOINED', roomCode: code, playerId, reconnected: isReconnect });
187	  send(room.host, { type: 'PLAYER_JOINED', playerId, reconnected: isReconnect });
188	  log(`room ${code}: ${playerId} ${isReconnect ? 'reconnected' : 'joined'} (${room.players.size} players)`);
189	}
190	
191	/** Player -> host. */
192	function relayToHost(ws, data) {
193	  const room = rooms.get(ws.meta.roomCode);
194	  if (!room) {
195	    sendError(ws, 'NOT_IN_ROOM', 'You are not in a game.');
196	    return;
197	  }
198	  room.lastActivity = Date.now();
199	  // Stamp the sender server-side so a phone cannot spoof another player.
200	  data.playerId = ws.meta.playerId;
201	  send(room.host, data);
202	}
203	
204	/** Host -> one player (when `targetPlayerId` is set) or all players. */
205	function relayToPlayers(ws, data) {
206	  const room = rooms.get(ws.meta.roomCode);
207	  if (!room) {
208	    sendError(ws, 'NOT_IN_ROOM', 'This host has no room.');
209	    return;
210	  }
211	  room.lastActivity = Date.now();
212	
213	  if (data.targetPlayerId) {
214	    const target = room.players.get(String(data.targetPlayerId).toUpperCase());
215	    if (target) send(target, data);
216	    return;
217	  }
218	
219	  for (const [, playerWs] of room.players) {
220	    send(playerWs, data);
221	  }
222	}
223	
224	// ---------------------------------------------------------------------------
225	// server
226	// ---------------------------------------------------------------------------
227	
228	// The controller page is served from this same origin on purpose. Motion sensors
229	// need a secure context, and an HTTPS page cannot open a plain ws:// socket — so
230	// splitting the page and the socket across two origins means fighting mixed
231	// content forever. One origin gives HTTPS and WSS together, and one tunnel
232	// (or one Fly app) covers both.
233	const STATIC_DIR = nodePath.resolve(__dirname, '..', 'controller');
234	
235	const CONTENT_TYPES = {
236	  '.html': 'text/html; charset=utf-8',
237	  '.js': 'text/javascript; charset=utf-8',
238	  '.css': 'text/css; charset=utf-8',
239	  '.json': 'application/json; charset=utf-8',
240	  '.svg': 'image/svg+xml',
241	  '.png': 'image/png',
242	  '.ico': 'image/x-icon',
243	};
244	
245	function serveStatic(req, res) {
246	  const requested = decodeURIComponent((req.url || '/').split('?')[0]);
247	  const relative = requested === '/' ? 'index.html' : requested.replace(/^\/+/, '');
248	  const resolved = nodePath.resolve(STATIC_DIR, relative);
249	
250	  // Refuse anything that escapes the static root.
251	  if (!resolved.startsWith(STATIC_DIR)) {
252	    res.writeHead(403).end('Forbidden');
253	    return;
254	  }
255	
256	  fs.readFile(resolved, (err, data) => {
257	    if (err) {
258	      res.writeHead(404, { 'Content-Type': 'text/plain' }).end('Not found');
259	      return;
260	    }
261	    const type = CONTENT_TYPES[nodePath.extname(resolved).toLowerCase()] || 'application/octet-stream';
262	    res.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'no-cache' }).end(data);
263	  });
264	}
265	
266	/**
267	 * QR module matrix for an arbitrary string, as JSON.
268	 *
269	 * Returns the raw black/white grid rather than a PNG so the caller renders it at
270	 * whatever size it needs — Unity draws this on a TV, where a fixed-resolution
271	 * image would either band or blur. Rows are strings of '0'/'1' because Unity's
272	 * JsonUtility cannot deserialize nested arrays.
273	 */
274	function serveQr(req, res, query) {
275	  const data = query.get('data');
276	
277	  if (!data || data.length > MAX_QR_DATA_LENGTH) {
278	    res.writeHead(400, { 'Content-Type': 'application/json' })
279	      .end(JSON.stringify({ error: `data must be 1..${MAX_QR_DATA_LENGTH} characters` }));
280	    return;
281	  }
282	
283	  try {
284	    // Type 0 picks the smallest version that fits. Level M survives the glare and
285	    // off-angle scanning you get pointing a phone at a television.
286	    const qr = qrcode(0, 'M');
287	    qr.addData(data);
288	    qr.make();
289	
290	    const size = qr.getModuleCount();
291	    const rows = [];
292	    for (let row = 0; row < size; row++) {
293	      let bits = '';
294	      for (let col = 0; col < size; col++) bits += qr.isDark(row, col) ? '1' : '0';
295	      rows.push(bits);
296	    }
297	
298	    res.writeHead(200, { 'Content-Type': 'application/json', 'Cache-Control': 'no-cache' })
299	      .end(JSON.stringify({ size, rows }));
300	  } catch (err) {
301	    res.writeHead(400, { 'Content-Type': 'application/json' })
302	      .end(JSON.stringify({ error: String(err.message || err) }));
303	  }
304	}
305	
306	const httpServer = http.createServer((req, res) => {
307	  // Base is a formality — only the path and query are ever read.
308	  const url = new URL(req.url || '/', 'http://localhost');
309	
310	  if (url.pathname === '/health') {
311	    res.writeHead(200, { 'Content-Type': 'application/json' })
312	      .end(JSON.stringify({ ok: true, rooms: rooms.size }));
313	    return;
314	  }
315	
316	  if (url.pathname === '/qr') {
317	    serveQr(req, res, url.searchParams);
318	    return;
319	  }
320	
321	  serveStatic(req, res);
322	});
323	
324	const wss = new WebSocketServer({ server: httpServer, maxPayload: MAX_MESSAGE_BYTES });
325	
326	wss.on('connection', (ws) => {
327	  ws.meta = {
328	    role: null,
329	    roomCode: null,
330	    playerId: null,
331	    isAlive: true,
332	    rateWindowStart: Date.now(),
333	    rateCount: 0,
334	  };
335	
336	  ws.on('pong', () => {
337	    ws.meta.isAlive = true;
338	  });
339	
340	  ws.on('message', (raw) => {
341	    if (isRateLimited(ws.meta)) return; // drop silently; a flooding client gets no feedback loop
342	
343	    let data;
344	    try {
345	      data = JSON.parse(raw);
346	    } catch {
347	      // The prototype let this throw, which killed the whole process and every
348	      // other room with it. One bad client must never take down the server.
349	      sendError(ws, 'BAD_JSON', 'Message was not valid JSON.');
350	      return;
351	    }
352	
353	    if (!data || typeof data !== 'object' || typeof data.type !== 'string') {
354	      sendError(ws, 'BAD_MESSAGE', 'Message must be an object with a "type".');
355	      return;
356	    }
357	
358	    switch (data.type) {
359	      case 'CREATE_ROOM':
360	        handleCreateRoom(ws);
361	        return;
362	      case 'JOIN_ROOM':
363	        handleJoinRoom(ws, data);
364	        return;
365	      case 'PING':
366	        send(ws, { type: 'PONG' });
367	        return;
368	      default:
369	        if (ws.meta.role === 'player') relayToHost(ws, data);
370	        else if (ws.meta.role === 'host') relayToPlayers(ws, data);
371	        else sendError(ws, 'NOT_REGISTERED', 'Send CREATE_ROOM or JOIN_ROOM first.');
372	    }
373	  });
374	
375	  ws.on('close', () => {
376	    const { role, roomCode, playerId } = ws.meta;
377	    if (!roomCode) return;
378	
379	    const room = rooms.get(roomCode);
380	    if (!room) return;
381	
382	    if (role === 'host' && room.host === ws) {
383	      closeRoom(room, 'Host disconnected');
384	      return;
385	    }
386	
387	    if (role === 'player' && room.players.get(playerId) === ws) {
388	      room.players.delete(playerId);
389	      send(room.host, { type: 'PLAYER_LEFT', playerId });
390	      log(`room ${roomCode}: ${playerId} left (${room.players.size} players)`);
391	    }
392	  });
393	
394	  ws.on('error', (err) => log('socket error:', err.message));
395	});
396	
397	// Drop sockets that stopped responding — phones that lose signal often never
398	// send a clean close frame, which would otherwise leak room slots forever.
399	const heartbeat = setInterval(() => {
400	  for (const ws of wss.clients) {
401	    if (!ws.meta) continue;
402	    if (!ws.meta.isAlive) {
403	      ws.terminate();
404	      continue;
405	    }
406	    ws.meta.isAlive = false;
407	    ws.ping();
408	  }
409	}, HEARTBEAT_MS);
410	
411	// Rooms whose host vanished without a close frame would otherwise persist for
412	// the lifetime of the process.
413	const roomSweep = setInterval(() => {
414	  const now = Date.now();
415	  for (const room of [...rooms.values()]) {
416	    if (now - room.lastActivity > ROOM_IDLE_TIMEOUT_MS) {
417	      closeRoom(room, 'Room idle timeout');
418	    }
419	  }
420	}, ROOM_SWEEP_MS);
421	
422	wss.on('close', () => {
423	  clearInterval(heartbeat);
424	  clearInterval(roomSweep);
425	});
426	
427	function shutdown() {
428	  log('shutting down');
429	  clearInterval(heartbeat);
430	  clearInterval(roomSweep);
431	  for (const room of [...rooms.values()]) closeRoom(room, 'Server shutting down');
432	  wss.close(() => httpServer.close(() => process.exit(0)));
433	  setTimeout(() => process.exit(0), 3000).unref();
434	}
435	
436	process.on('SIGTERM', shutdown);
437	process.on('SIGINT', shutdown);
438	
439	httpServer.listen(PORT, () => {
440	  log(`Rock Skipping relay listening on :${PORT}`);
441	  log(`  controller page  http://localhost:${PORT}/`);
442	  log(`  websocket        ws://localhost:${PORT}/`);
443	  log(`  serving static from ${STATIC_DIR}`);
444	});
445

