1	'use strict';
2	
3	/**
4	 * Integration test for the relay. Spawns server.js on a scratch port and exercises
5	 * the routing plus each hardening fix. Run with: npm test
6	 */
7	
8	const { WebSocket } = require('ws');
9	const { spawn } = require('child_process');
10	const http = require('http');
11	const path = require('path');
12	
13	const PORT = 3999;
14	const URL = `ws://127.0.0.1:${PORT}`;
15	
16	let failures = 0;
17	
18	function check(label, ok, detail) {
19	  console.log(`  ${ok ? 'PASS' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`);
20	  if (!ok) failures++;
21	}
22	
23	function connect() {
24	  return new Promise((resolve, reject) => {
25	    const ws = new WebSocket(URL);
26	    ws.inbox = [];
27	    ws.waiters = [];
28	    ws.on('message', (raw) => {
29	      let msg;
30	      try { msg = JSON.parse(raw); } catch { return; }
31	      const waiter = ws.waiters.shift();
32	      if (waiter) waiter(msg);
33	      else ws.inbox.push(msg);
34	    });
35	    ws.on('open', () => resolve(ws));
36	    ws.on('error', reject);
37	  });
38	}
39	
40	function next(ws, timeoutMs = 2000) {
41	  if (ws.inbox.length) return Promise.resolve(ws.inbox.shift());
42	  return new Promise((resolve, reject) => {
43	    const timer = setTimeout(() => reject(new Error('timed out waiting for a message')), timeoutMs);
44	    ws.waiters.push((msg) => { clearTimeout(timer); resolve(msg); });
45	  });
46	}
47	
48	function send(ws, obj) {
49	  ws.send(JSON.stringify(obj));
50	}
51	
52	function httpGet(pathAndQuery) {
53	  return new Promise((resolve, reject) => {
54	    http.get({ host: '127.0.0.1', port: PORT, path: pathAndQuery }, (res) => {
55	      let body = '';
56	      res.on('data', (chunk) => { body += chunk; });
57	      res.on('end', () => resolve({ status: res.statusCode, body }));
58	    }).on('error', reject);
59	  });
60	}
61	
62	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
63	
64	async function run() {
65	  console.log('Relay integration test\n');
66	
67	  // ---- routing basics -----------------------------------------------------
68	  const host = await connect();
69	  send(host, { type: 'CREATE_ROOM' });
70	  const created = await next(host);
71	
72	  check('host receives ROOM_CREATED', created.type === 'ROOM_CREATED');
73	  const code = created.roomCode;
74	  check('room code is 4 characters', typeof code === 'string' && code.length === 4, code);
75	  check('room code avoids ambiguous I/O', !/[IO]/.test(code), code);
76	
77	  // ---- fix: joins to a missing room must be answered, not ignored ----------
78	  const stranger = await connect();
79	  send(stranger, { type: 'JOIN_ROOM', roomCode: 'ZZZZ', playerId: 'NOBODY' });
80	  const rejected = await next(stranger);
81	  check('join to unknown room is rejected', rejected.type === 'ERROR' && rejected.code === 'ROOM_NOT_FOUND',
82	    `${rejected.type}/${rejected.code}`);
83	  stranger.close();
84	
85	  // ---- normal join --------------------------------------------------------
86	  const player = await connect();
87	  send(player, { type: 'JOIN_ROOM', roomCode: code, playerId: 'aj' });
88	  const joined = await next(player);
89	  check('player receives JOINED', joined.type === 'JOINED');
90	  check('player id is normalised to uppercase', joined.playerId === 'AJ', joined.playerId);
91	
92	  const hostSawJoin = await next(host);
93	  check('host is told PLAYER_JOINED', hostSawJoin.type === 'PLAYER_JOINED' && hostSawJoin.playerId === 'AJ');
94	
95	  // ---- player -> host, with server-side identity stamping ------------------
96	  send(player, { type: 'THROW', playerId: 'SOMEONE_ELSE', power: 0.72 });
97	  const throwMsg = await next(host);
98	  check('THROW reaches the host', throwMsg.type === 'THROW' && throwMsg.power === 0.72);
99	  check('spoofed playerId is overwritten by the server', throwMsg.playerId === 'AJ', throwMsg.playerId);
100	
101	  // ---- host -> players ----------------------------------------------------
102	  send(host, { type: 'SPECTATE', liveSkips: 3 });
