2	using System.Collections.Concurrent;
3	using System.Net.WebSockets;
4	using System.Text;
5	using System.Threading;
6	using System.Threading.Tasks;
7	using EventSystems;
8	using EventTypes.MatchEvents;
9	using Singleton;
10	using UnityEngine;
11	
12	namespace Net
13	{
14	    /// <summary>
15	    /// Host-side connection to the relay. Creates the room, receives phone input,
16	    /// and broadcasts match state back out.
17	    /// </summary>
18	    /// <remarks>
19	    /// MUST live in the Bootstrap scene as a persistent manager. If it is created
20	    /// per-scene instead, the socket is torn down on every transition and every
21	    /// phone bounces back to the join screen — a lifecycle bug that presents as a
22	    /// networking one.
23	    ///
24	    /// DEVIATION FROM PLAN: uses System.Net.WebSockets.ClientWebSocket rather than
25	    /// the NativeWebSocket package the plan named. ClientWebSocket ships with .NET,
26	    /// so there is no external dependency to vendor, and it works fine for a native
27	    /// desktop host. The tradeoff is that it does NOT work in WebGL builds — which
28	    /// is acceptable because the plan already rejected WebGL as a target. Swap to
29	    /// NativeWebSocket if a browser build ever becomes a requirement.
30	    ///
31	    /// ClientWebSocket is thread-affine for sends, so all sends funnel through a
32	    /// semaphore, and all received messages are marshalled onto the main thread via
33	    /// a queue drained in Update — Unity APIs cannot be touched from the socket task.
34	    /// </remarks>
35	    public class RelayClient : SingletonBase<RelayClient>
36	    {
37	        [Tooltip("ws://localhost:3000 for local dev; wss://<your-app>.fly.dev in production.")]
38	        [SerializeField] private string relayUrl = "ws://localhost:3000";
39	        [SerializeField] private bool verboseLogging;
40	
41	        public string RoomCode { get; private set; }
42	        public bool IsConnected => _socket != null && _socket.State == WebSocketState.Open;
43	
44	        /// <summary>Cosmetic aim frames. Safe to drop; never feed these to the simulation.</summary>
45	        public event Action<AimMessage> AimReceived;
46	
47	        /// <summary>The authoritative throw for a turn.</summary>
48	        public event Action<ThrowMessage> ThrowReceived;
49	
50	        public event Action<string> RoomCodeAssigned;
51	
52	        private ClientWebSocket _socket;
53	        private CancellationTokenSource _cts;
54	        private readonly ConcurrentQueue<string> _inbound = new();
55	        private readonly SemaphoreSlim _sendLock = new(1, 1);
56	
57	        private bool _connecting;
58	        private float _nextRetryTime;
59	        private float _retryDelay = 1f;
60	        private const float MaxRetryDelay = 10f;
61	
62	        protected override void Awake()
63	        {
64	            persistBetweenScenes = true;
65	            base.Awake();
66	        }
67	
68	        private void Start()
69	        {
70	            _ = ConnectAsync();
71	        }
72	
73	        private void Update()
74	        {
75	            // Everything that touches Unity happens here, on the main thread.
76	            while (_inbound.TryDequeue(out var json))
77	            {
78	                Dispatch(json);
79	            }
80	
81	            if (!IsConnected && !_connecting && Time.time >= _nextRetryTime)
82	            {
83	                _ = ConnectAsync();
84	            }
85	        }
86	
87	        private async Task ConnectAsync()
88	        {
89	            if (_connecting) return;
90	            _connecting = true;
91	
92	            try
93	            {
94	                _cts?.Cancel();
95	                _socket?.Dispose();
96	
97	                _cts = new CancellationTokenSource();
98	                _socket = new ClientWebSocket();
99	
100	                await _socket.ConnectAsync(new Uri(relayUrl), _cts.Token);
101	                Debug.Log($"[RelayClient] Connected to {relayUrl}");
102	
103	                _retryDelay = 1f;
104	                await SendRawAsync($"{{\"type\":\"{MessageType.CreateRoom}\"}}");
105	
106	                _ = ReceiveLoopAsync(_socket, _cts.Token);
107	            }
108	            catch (Exception e)
109	            {
110	                // Backoff rather than hammering a relay that is down or still booting.
111	                _retryDelay = Mathf.Min(_retryDelay * 2f, MaxRetryDelay);
112	                _nextRetryTime = Time.time + _retryDelay;
113	                Debug.LogWarning($"[RelayClient] Connect failed ({e.Message}); retrying in {_retryDelay:F0}s");
114	            }
115	            finally
116	            {
117	                _connecting = false;
118	            }
119	        }
120	
121	        private async Task ReceiveLoopAsync(ClientWebSocket socket, CancellationToken token)
122	        {
123	            var buffer = new byte[8192];
124	            var builder = new StringBuilder();
125	
126	            try
127	            {
128	                while (!token.IsCancellationRequested && socket.State == WebSocketState.Open)
129	                {
130	                    var result = await socket.ReceiveAsync(new ArraySegment<byte>(buffer), token);
131	
132	                    if (result.MessageType == WebSocketMessageType.Close) break;
133	
134	                    builder.Append(Encoding.UTF8.GetString(buffer, 0, result.Count));
135	
136	                    // A single message can arrive across several frames.
137	                    if (!result.EndOfMessage) continue;
138	
139	                    _inbound.Enqueue(builder.ToString());
140	                    builder.Clear();
141	                }
142	            }
143	            catch (OperationCanceledException) { /* shutting down */ }
144	            catch (Exception e)
145	            {
146	                Debug.LogWarning($"[RelayClient] Receive loop ended: {e.Message}");
147	            }
148	
149	            _nextRetryTime = Time.time + _retryDelay;
150	        }
151	
152	        private void Dispatch(string json)
153	        {
154	            MessageEnvelope envelope;
155	            try
156	            {
157	                envelope = JsonUtility.FromJson<MessageEnvelope>(json);
158	            }
159	            catch (Exception e)
160	            {
161	                Debug.LogWarning($"[RelayClient] Unparseable message dropped: {e.Message}");
162	                return;
163	            }
164	
165	            if (envelope == null || string.IsNullOrEmpty(envelope.type)) return;
166	            if (verboseLogging) Debug.Log($"[RelayClient] <- {json}");
167	
168	            switch (envelope.type)
169	            {
170	                case MessageType.RoomCreated:
171	                {
172	                    RoomCode = JsonUtility.FromJson<RoomCreatedMessage>(json).roomCode;
173	                    Debug.Log($"[RelayClient] Room code: {RoomCode}");
174	                    RoomCodeAssigned?.Invoke(RoomCode);
175	                    break;
176	                }
177	
178	                case MessageType.PlayerJoined:
179	                {
180	                    var joined = JsonUtility.FromJson<PlayerJoinedMessage>(json);
181	                    EventManager.Instance?.Publish(new PlayerJoinedEvent(joined.playerId, joined.reconnected));
182	                    break;
183	                }
184	
185	                case MessageType.PlayerLeft:
186	                {
187	                    var left = JsonUtility.FromJson<PlayerLeftMessage>(json);
188	                    EventManager.Instance?.Publish(new PlayerLeftEvent(left.playerId));
189	                    break;
190	                }
191	
192	                case MessageType.Aim:
193	                    AimReceived?.Invoke(JsonUtility.FromJson<AimMessage>(json));
194	                    break;
195	
196	                case MessageType.Throw:
197	                    ThrowReceived?.Invoke(JsonUtility.FromJson<ThrowMessage>(json));
198	                    break;
199	
200	                case MessageType.Error:
201	                {
202	                    var error = JsonUtility.FromJson<ErrorMessage>(json);
203	                    Debug.LogWarning($"[RelayClient] Relay error {error.code}: {error.message}");
204	                    break;
205	                }
206	            }
207	        }
208	
209	        /// <summary>Fire-and-forget send. Safe to call every frame from the main thread.</summary>
210	        public void Send(string json)
211	        {
212	            if (!IsConnected) return;
213	            _ = SendRawAsync(json);
214	        }
215	
216	        private async Task SendRawAsync(string json)
217	        {
218	            // ClientWebSocket forbids overlapping sends; the semaphore serialises them.
219	            await _sendLock.WaitAsync();
220	            try
221	            {
222	                if (_socket?.State != WebSocketState.Open) return;
223	                var bytes = Encoding.UTF8.GetBytes(json);
224	                await _socket.SendAsync(new ArraySegment<byte>(bytes), WebSocketMessageType.Text, true, _cts.Token);
225	            }
226	            catch (Exception e)
227	            {
228	                Debug.LogWarning($"[RelayClient] Send failed: {e.Message}");
229	            }
230	            finally
231	            {
232	                _sendLock.Release();
233	            }
234	        }
235	
236	        protected override void OnDestroy()
237	        {
238	            _cts?.Cancel();
239	            _socket?.Dispose();
240	            _sendLock.Dispose();
241	            EventManager.Instance?.UnsubscribeFromAllEvents(this);
242	            base.OnDestroy();
243	        }
244	    }
245	}
